BEGIN;

UPDATE ensino.horario_turma
SET data_inicio='2026-02-09'
WHERE id_horario_turma in(1419893, 1419888, 1419890);

UPDATE ensino.horario_turma
SET data_inicio='2026-02-09',data_fim='2026-12-19'
WHERE id_horario_turma in(1419875, 1419885);

DELETE FROM ensino.horario_turma
WHERE id_horario_turma in (1414963, 1414983, 1414978, 1414985, 1414980);

-- CRIANDO TABELAS TEMPORÁRIAS PARA REALIZAR AS ALTERAÇÕES NOS HORÁRIOS DAS TURMAS DAS ESCOLAS LISTADAS NO PDF
-- ANEXADO NA TAREFA
select ts.id_turma_serie 
into temp turmas_ajuste
from basico.turma_serie ts 
join escola.escola e on e.id_escola  = ts.id_escola 
and ts.id_turma_serie in(52019384, 52019654, 52019377, 52019665, 52018725, 52018731, 52019792, 52020135, 52019808, 52020140, 52015337, 52015360,
						52017919, 52017958, 52018255, 52018285, 52018300, 52020659, 52018364, 52018365, 52014150, 52013418, 52013455, 52020924, 52020900,
