						52020801, 52020802, 52020804, 52020814, 52036084, 52043938, 52102954, 52019540, 52019544, 52019554, 52019562, 51955550, 51955553, 51955554,
						51955555, 51961805, 51961808, 51961810, 51961811);

select ht.id_horario_turma, ht.data_inicio, ht.data_fim, ht.ativo
into temp horarios_alteracao
from ensino.horario_turma ht 
join ensino.turma t on t.id_turma = ht.id_turma 
join basico.turma_serie ts on ts.id_turma_serie = t.id_turma_serie 
where ts.id_turma_serie in (
	select id_turma_serie from turmas_ajuste
);

--CRIANDO SCRIPTS PARA ALTERAÇÃO NAS ESCOLAS LISTADAS NO PDF
--BACKUP
SELECT
'UPDATE ensino.horario_turma
SET data_inicio = ''' || COALESCE(horarios_alteracao.data_inicio::text, 'NULL') || ''',
    data_fim = ''' || COALESCE(horarios_alteracao.data_fim::text, 'NULL') || '''
WHERE id_horario_turma = ' || horarios_alteracao.id_horario_turma || ';' AS backup
FROM horarios_alteracao
WHERE ativo;


